// Define the UserProfile type
interface UserProfile {
  id: string;
  name: string;
  email: string;
  avatarUrl?: string;
  createdAt: string;
}

// Define custom error types for better error handling
class NetworkTimeoutError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'NetworkTimeoutError';
  }
}

class ServerError extends Error {
  constructor(message: string, public statusCode: number) {
    super(message);
    this.name = 'ServerError';
  }
}

/**
 * Fetches a user profile from an external API
 * @param userId - The unique identifier of the user
 * @returns A promise that resolves to the user profile
 * @throws NetworkTimeoutError if the request times out
 * @throws ServerError if the server returns a 500 error
 */
export async function fetchUserProfile(
  userId: string
): Promise<UserProfile> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 5000); // 5 second timeout

  try {
    const response = await fetch(`/api/users/${userId}`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      if (response.status === 500) {
        throw new ServerError('Internal server error', response.status);
      }
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();

    // Validate the response structure
    if (!data.id || !data.name || !data.email) {
      throw new Error('Invalid user profile data received');
    }

    return data as UserProfile;
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') {
      throw new NetworkTimeoutError('Request timed out');
    }
    throw error;
  }
}
